type JsonSchema = Record<string, any>;

function propertyTypeLabel(schema: JsonSchema): string {
  if (Array.isArray(schema.enum) && schema.enum.length > 0) {
    return schema.enum
      .map((value: unknown) => JSON.stringify(value))
      .join(" | ");
  }
  if (schema.type === "array") {
    return `array<${propertyTypeLabel(schema.items ?? { type: "value" })}>`;
  }
  return typeof schema.type === "string" ? schema.type : "value";
}

function describeParameter(
  name: string,
  schema: JsonSchema,
  required: Set<string>,
): string {
  const requirement = required.has(name) ? "required" : "optional";
  const defaultValue = Object.hasOwn(schema, "default")
    ? ` Default: ${JSON.stringify(schema.default)}.`
    : "";
  const description =
    typeof schema.description === "string" && schema.description.trim()
      ? schema.description.trim()
      : "No additional description.";
  return `- \`${name}\` (${requirement}, ${propertyTypeLabel(schema)}): ${description}${defaultValue}`;
}

export function describeToolParameters(
  parameters: Record<string, unknown>,
  required: string[] = [],
): string {
  const entries = Object.entries(parameters);
  if (entries.length === 0) return "Parameters: none.";
  const requiredSet = new Set(required);
  return [
    "Parameters:",
    ...entries.map(([name, schema]) =>
      describeParameter(name, schema as JsonSchema, requiredSet),
    ),
  ].join("\n");
}

function parameterError(path: string, message: string): string {
  return `${path || "arguments"} ${message}`;
}

function validateSchema(
  value: unknown,
  schema: JsonSchema,
  path: string,
): string | null {
  if (value === undefined) return null;
  if (schema.type === "string" && typeof value !== "string")
    return parameterError(path, "must be a string.");
  if (
    schema.type === "number" &&
    (typeof value !== "number" || !Number.isFinite(value))
  )
    return parameterError(path, "must be a finite number.");
  if (schema.type === "integer" && !Number.isInteger(value))
    return parameterError(path, "must be an integer.");
  if (schema.type === "boolean" && typeof value !== "boolean")
    return parameterError(path, "must be a boolean.");
  if (schema.type === "array") {
    if (!Array.isArray(value)) return parameterError(path, "must be an array.");
    if (typeof schema.minItems === "number" && value.length < schema.minItems) {
      return parameterError(
        path,
        `must contain at least ${schema.minItems} item${schema.minItems === 1 ? "" : "s"}.`,
      );
    }
    if (schema.items) {
      for (let index = 0; index < value.length; index += 1) {
        const error = validateSchema(
          value[index],
          schema.items,
          `${path}[${index}]`,
        );
        if (error) return error;
      }
    }
  }
  if (schema.type === "object") {
    if (!value || typeof value !== "object" || Array.isArray(value))
      return parameterError(path, "must be an object.");
    const objectValue = value as Record<string, unknown>;
    const required = Array.isArray(schema.required) ? schema.required : [];
    for (const name of required) {
      if (
        (objectValue[name] === undefined ||
          objectValue[name] === null ||
          objectValue[name] === "") &&
        schema["x-keating-drop-invalid-item"] !== true
      ) {
        return parameterError(`${path}.${name}`, "is required.");
      }
    }
    for (const [name, childSchema] of Object.entries(schema.properties ?? {})) {
      const error = validateSchema(
        objectValue[name],
        childSchema as JsonSchema,
        `${path}.${name}`,
      );
      if (error) return error;
    }
    if (schema.additionalProperties === false) {
      const allowed = new Set(Object.keys(schema.properties ?? {}));
      const unknown = Object.keys(objectValue).find(
        (name) => !allowed.has(name),
      );
      if (unknown)
        return parameterError(`${path}.${unknown}`, "is not supported.");
    }
  }
  if (
    Array.isArray(schema.enum) &&
    !schema.enum.includes(value) &&
    schema["x-keating-normalize-invalid-enum"] !== true
  ) {
    return parameterError(
      path,
      `must be one of ${schema.enum.map((item: unknown) => JSON.stringify(item)).join(", ")}.`,
    );
  }
  return null;
}

function validateToolArguments(
  name: string,
  params: Record<string, unknown>,
  parameters: Record<string, unknown>,
  required: string[],
): void {
  const schema = {
    type: "object",
    properties: parameters,
    required,
    additionalProperties: false,
  };
  const validationError = validateSchema(params, schema, "arguments");
  if (!validationError) return;
  throw new KeatingToolError(
    name,
    `${validationError}\n\n${describeToolParameters(parameters, required)}`,
    "invalid-arguments",
  );
}

const FAILURE_RESULT_PATTERNS = [
  /^error:/i,
  /^#\s+.+\bfailed\b/i,
  /^capability unavailable:/i,
  /^[^\n]*\bis not (?:active|available|connected)\b/i,
  /^no (?:image generation model|valid .+ supplied)\b/i,
  /^not ready to\b/i,
  /^author the\b/i,
  /^pick a valid\b/i,
  /^choose a valid\b/i,
  /^[^\n]*\b(?:is|are) required\b/i,
  /^[^\n]*\bmust be\b/i,
];

export function toolFailureMessage(result: string): string | null {
  const trimmed = result.trim();
  if (!trimmed) return "Tool returned an empty result.";
  return FAILURE_RESULT_PATTERNS.some((pattern) => pattern.test(trimmed))
    ? trimmed
    : null;
}

