					`- scope: ${scope}`,
					`- hypothesis: ${hypothesis}`,
					targetObjectives.length ? `- target objectives: ${targetObjectives.join(", ")}` : "",
					"",
					result,
				].filter((line) => line !== "").join("\n");
			},
			["scope", "hypothesis"],
		),
	];
