export function classifyTool(name: string): ToolSecurityDescriptor {
  const risk = KEATING_TOOL_RISKS[name];
  return risk
    ? { name, risk, known: true }
    : { name, risk: "code-execution", known: false, allowVoice: false };
}

export function evaluateToolPermission(
  request: ToolPermissionRequest,
): ToolPermissionDecision {
  const { tool, surface, provenance } = request;
  const reasons: string[] = [];
  const untrusted = isUntrustedProvenance(provenance);
  const independentlyAuthorized = hasIndependentUserAuthorization(provenance);
  const secretBearing =
    tool.sensitiveArguments === true || containsLikelySecret(request.arguments);

  if (tool.known === false) {
    return decision("deny", tool.risk, [
      "Unknown tools are not part of Keating's callable surface.",
    ]);
  }

  if (
    surface === "voice" &&
    (tool.allowVoice === false || NEVER_VOICE.has(tool.risk))
  ) {
    return decision("deny", tool.risk, [
      "This tool is not available from voice input.",
    ]);
  }

  if (surface === "voice" && secretBearing) {
    return decision("deny", tool.risk, [
      "Secret-bearing arguments are not available from voice input.",
    ]);
  }

  if (untrusted && !independentlyAuthorized) {
    if (tool.risk === "code-execution" || tool.risk === "destructive") {
      return decision("deny", tool.risk, [
        "Untrusted web content cannot trigger code execution or destructive actions.",
      ]);
    }
  }

  return decision("allow", tool.risk, reasons);
}

function decision(
  outcome: ToolPermissionDecision["outcome"],
  risk: ToolRiskClass,
  reasons: readonly string[],
): ToolPermissionDecision {
  return { outcome, risk, reasons };
}
