        agentEvents = [...agentEvents.slice(0, -1), { ...previous, text: previous.text + text }];
      } else {
        agentEvents = [...agentEvents, {
          id: createId("event"), occurredAt: new Date().toISOString(), type, turnId,
          sequence: eventSequence++, text,
        }];
      }
      traceDirty = true;
