    const appendToolCall = (call: { id: string; name: string; arguments: Record<string, unknown> }) => {
      const callId = contractId(call.id, "call");
      agentEvents = [...agentEvents, {
        id: createId("event"), occurredAt: new Date().toISOString(), type: "tool-call", turnId,
        sequence: eventSequence++,
        call: { id: callId, name: call.name.slice(0, 128) || "unknown", arguments: call.arguments, idempotencyKey: contractId(`tool-${callId}`, "tool-key") },
      }];
      traceDirty = true;
